package ch.hewa.screenshot;
import android.app.*;import android.content.*;import android.media.projection.*;import android.os.*;import android.provider.Settings;import android.net.Uri;import android.graphics.Color;import android.view.Gravity;import android.widget.*;
public class MainActivity extends Activity{
 static final int REQ=100;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setGravity(Gravity.CENTER);box.setPadding(40,50,40,50);box.setBackgroundColor(Color.rgb(15,24,75));TextView title=new TextView(this);title.setText("✦ HEWA Screenshot");title.setTextSize(29);title.setTextColor(Color.WHITE);box.addView(title);TextView sub=new TextView(this);sub.setText("Cattura ciò che conta\n\nUn tocco sul pulsante flottante per salvare uno screenshot nella galleria.");sub.setTextSize(18);sub.setTextColor(0xffbdefff);sub.setPadding(0,40,0,45);box.addView(sub);Button start=new Button(this);start.setText("ATTIVA SCREENSHOT");box.addView(start);start.setOnClickListener(v->{if(!Settings.canDrawOverlays(this)){Intent o=new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()));startActivity(o);Toast.makeText(this,"Consenti la visualizzazione sopra le altre app, poi torna qui",Toast.LENGTH_LONG).show();return;}startActivityForResult(getSystemService(MediaProjectionManager.class).createScreenCaptureIntent(),REQ);});Button stop=new Button(this);stop.setText("TERMINA");box.addView(stop);stop.setOnClickListener(v->stopService(new Intent(this,ServiceCapture.class)));setContentView(box);}
 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=REQ||result!=RESULT_OK||data==null)return;Intent i=new Intent(this,ServiceCapture.class);i.putExtra("result",result);i.putExtra("data",data);startForegroundService(i);moveTaskToBack(true);}
}